replacements.new:
var HGameButton NewGameButton;
var HGameButton MultiplayerButton;
var HPMultiplayerPage MultiplayerPage;

Super.Created();
NewGameButton = HGameButton(CreateControl(Class'HGameButton',205.0,137.0,230.0,26.0));
NewGameButton.SetFont(F_HPMenuLarge);
NewGameButton.TextColor.R = 250;
NewGameButton.TextColor.G = 250;
NewGameButton.TextColor.B = 250;
NewGameButton.bColorOver = True;
NewGameButton.Align = TA_Center;
NewGameButton.SetText("Single Player");
NewGameButton.ToolTipString = "Start the original campaign";
MultiplayerButton = HGameButton(CreateControl(Class'HGameButton',205.0,170.0,230.0,26.0));
MultiplayerButton.SetFont(F_HPMenuLarge);
MultiplayerButton.TextColor.R = 250;
MultiplayerButton.TextColor.G = 250;
MultiplayerButton.TextColor.B = 250;
MultiplayerButton.bColorOver = True;
MultiplayerButton.Align = TA_Center;
MultiplayerButton.SetText("Multiplayer");
MultiplayerButton.ToolTipString = "Co-op or Versus";
LegalText = Localize("all","legal_title_01","Pickup");

case NewGameButton:
FEBook(book).bGamePlaying = True;
FEBook(book).CloseBook();
GetPlayerOwner().ClientTravel("PrivetDr.unr?game=Engine.GameInfo", TRAVEL_Absolute, False);
break;
case MultiplayerButton:
if ( MultiplayerPage == None )
    MultiplayerPage = HPMultiplayerPage(FEBook(book).CreatePage(Class'HPMultiplayerPage', "MULTIPLAYER"));
if ( MultiplayerPage != None ) FEBook(book).ChangePage(MultiplayerPage);
break;
